option.value:
:host {
  display: block;
}

* {
  box-sizing: border-box;
}

.board-page {
  --green: #00884f;
  --deep-green: #003f2e;
  --yellow: #ffd229;
  --ink: #303030;
  --muted: #6d6d6d;
  --line: #d7eee4;
  background: #ffffff;
  color: var(--ink);
  font-family: "Plus Jakarta Sans", "Source Sans 3", "Inter", "Segoe UI", Arial, sans-serif;
  margin: 0;
  min-height: 100vh;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  display: block;
  max-width: 100%;
}

.site-header {
  background: #ffffff;
}

.topbar {
  align-items: center;
  background: var(--yellow);
  color: #0e0e0e;
  display: flex;
  font-size: 16px;
  font-weight: 600;
  height: 60px;
  justify-content: space-between;
  padding: 0 95px;
}

.contact-line,
.utility-nav,
.primary-nav {
  align-items: center;
  display: flex;
}

.contact-line {
  gap: 18px;
}

.contact-line span:nth-child(2) {
  margin-right: 6px;
}

.utility-nav {
  gap: 36px;
}

.main-nav {
  align-items: center;
  display: grid;
  grid-template-columns: 320px 1fr 132px;
  height: 132px;
  padding: 0 99px;
}

.brand {
  align-items: center;
  color: var(--green);
  display: inline-flex;
  font-size: 22px;
  font-weight: 800;
  gap: 4px;
  letter-spacing: 0;
}

.brand img {
  height: 66px;
  object-fit: contain;
  width: 54px;
}

.brand.light {
  color: #ffffff;
  font-size: 13px;
}

.brand.light img {
  height: 32px;
  width: 28px;
}

.primary-nav {
  color: #444444;
  font-size: 20px;
  gap: 34px;
  justify-content: center;
}

.primary-nav .active {
  color: var(--green);
  font-weight: 700;
}

.nav-cta {
  align-items: center;
  background: var(--yellow);
  border: 0;
  border-radius: 999px;
  color: #141414;
  display: inline-flex;
  font-size: 17px;
  /*font-weight: 700;*/
  height: 52px;
  justify-content: center;
  white-space: nowrap;
}

.hero-section {
  margin: 40px;
  overflow: hidden;
  position: relative;
  border-radius: 25px;
  height: 500px;
}

.hero-section img {
  height: 100%;
  object-fit: cover;
  width: 100%;
}

.hero-overlay {
  background: linear-gradient(180deg, rgba(0, 71, 53, 0.06) 0%, rgba(0, 64, 48, 0.52) 48%, rgba(0, 48, 34, 0.98) 100%);
  inset: 0;
  position: absolute;
}

.hero-intro {
  color: #ffffff;
  left: 50%;
  position: absolute;
  text-align: center;
  top: 50%;
  transform: translate(-50%, -50%);
  width: calc(100% - 180px);
  max-width: 800px;
}

.hero-intro h1 {
  color: #ffffff;
  font-size: 64px;
  font-weight: 700;
  line-height: 1.2;
  margin: 0 0 16px;
}

.hero-intro p {
  font-size: 24px;
  line-height: 1.4;
  margin: 0;
}

.profile-section {
  padding-top: 80px;
  padding-bottom: 100px;
}

.profile-container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
  width: 100%;
  max-width: 1200px;
  align-items: flex-end;
}

.profile-content {
  display: flex;
  flex-direction: column;
}

.profile-content h2 {
  color: #272727;
  font-size: 36px;
  font-weight: 700;
  line-height: 1.2;
  margin: 0 0 12px;
}

.chairman-title {
  color: #6d6d6d;
  font-size: 15px;
  line-height: 1.6;
  margin: 0 0 24px;
}

.chairman-badge {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  background: #fff5e6;
  border-radius: 8px;
  padding: 12px 16px;
  width: fit-content;
}

.badge-icon {
  font-size: 20px;
}

.badge-text {
  color: #6d6d6d;
  font-size: 13px;
  font-weight: 500;
}

.profile-image {
  border-radius: 12px;
  overflow: visible;
  position: relative;
}

.profile-image img {
  width: 100%;
  height: auto;
  display: block;
  border-radius: 12px;
}

.section-block {
  align-items: center;
  display: flex;
  flex-direction: column;
  padding: 80px 99px 100px;
}

.section-title {
  margin-bottom: 50px;
  max-width: 900px;
  text-align: center;
}

.section-title h2 {
  color: #272727;
  font-size: 36px;
  font-weight: 700;
  letter-spacing: 0;
  line-height: 1.2;
  margin: 0 0 16px;
}

.section-title p {
  color: var(--muted);
  font-size: 14px;
  line-height: 1.7;
  margin: 0;
}

.board-intro {
  padding-top: 60px;
  padding-bottom: 80px;
}

.trustees-grid {
  width: 100%;
  padding-top: 60px;
  padding-bottom: 100px;
}

.trustees-container {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 32px;
  width: 100%;
  max-width: 1200px;
}

.trustee-card {
  border: none;
  border-radius: 12px;
  overflow: hidden;
  transition: all 0.3s ease;
  background: #ffffff;
}

.trustee-card:hover {
  box-shadow: 0 12px 32px rgba(0, 136, 79, 0.15);
}

.trustee-avatar {
  width: 100%;
  height: 320px;
  overflow: hidden;
  border-radius: 12px 12px 0 0;
  background: #f5f5f5;
}

.trustee-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.trustee-info {
  padding: 24px 20px;
}

.trustee-info h3 {
  color: #2b2b2b;
  font-size: 17px;
  font-weight: 700;
  margin: 0 0 8px;
}

.trustee-info .position {
  color: var(--green);
  font-size: 12px;
  font-weight: 700;
  margin: 0 0 12px;
}

.trustee-info .bio {
  color: #6d6d6d;
  font-size: 12px;
  line-height: 1.6;
  margin: 0;
}

.board-mission {
  background: #f9f9f9;
  padding-top: 80px;
  padding-bottom: 80px;
  width: 100%;
}

.mission-content {
  width: 100%;
  max-width: 1200px;
}

.mission-content h2 {
  color: #272727;
  font-size: 39px;
  font-weight: 800;
  text-align: center;
  margin: 0 0 60px;
}

.mission-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 48px;
  width: 100%;
}

.mission-item {
  background: #ffffff;
  border-radius: 12px;
  padding: 40px 32px;
  border: 1px solid #e8e8e8;
}

.mission-item h3 {
  color: var(--green);
  font-size: 20px;
  font-weight: 800;
  margin: 0 0 16px;
}

.mission-item p {
  color: #5d5d5d;
  font-size: 14px;
  line-height: 1.7;
  margin: 0;
}

.footer {
  background: var(--green);
  border-radius: 10px;
  color: #ffffff;
  display: grid;
  gap: 52px;
  grid-template-columns: 1.8fr 0.9fr 1.05fr 0.95fr;
  margin: 40px;
  min-height: 664px;
  padding: 110px 80px 70px;
  position: relative;
}

.footer p {
  color: rgba(255, 255, 255, 0.8);
  font-size: 13px;
  line-height: 1.6;
  margin: 32px 0 22px;
  max-width: 360px;
}

.footer nav {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.footer h3 {
  font-size: 15px;
  margin: 0 0 8px;
}

.footer a,
.footer address {
  color: rgba(255, 255, 255, 0.8);
  font-size: 12px;
  font-style: normal;
  line-height: 1.5;
}

.socials {
  display: flex;
  gap: 16px;
}

.socials a {
  color: #ffffff;
  font-size: 18px;
}

.footer address {
  bottom: 98px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  position: absolute;
  right: 90px;
}

.footer small {
  bottom: 70px;
  color: rgba(255, 255, 255, 0.78);
  font-size: 11px;
  left: 80px;
  position: absolute;
}

@media (max-width: 1180px) {
  .topbar,
  .main-nav {
    padding-left: 32px;
    padding-right: 32px;
  }

  .topbar,
  .main-nav,
  .primary-nav {
    gap: 18px;
  }

  .main-nav {
    grid-template-columns: 1fr;
    height: auto;
    padding-bottom: 24px;
    padding-top: 24px;
  }

  .primary-nav,
  .utility-nav {
    flex-wrap: wrap;
    justify-content: flex-start;
  }

  .trustees-container {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .mission-grid {
    grid-template-columns: 1fr;
    gap: 32px;
  }
}

@media (max-width: 820px) {
  .topbar {
    align-items: flex-start;
    flex-direction: column;
    height: auto;
    padding-bottom: 16px;
    padding-top: 16px;
  }

  .hero-section {
    margin-left: 16px;
    margin-right: 16px;
    height: 350px;
  }

  .hero-intro h1 {
    font-size: 40px;
  }

  .hero-intro p {
    font-size: 18px;
  }

  .section-block {
    padding-left: 22px;
    padding-right: 22px;
  }

  .trustees-container {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .footer {
    grid-template-columns: 1fr;
    margin-left: 16px;
    margin-right: 16px;
    padding: 48px 28px 120px;
    gap: 28px;
    min-height: 0;
  }

  .footer address,
  .footer small {
    bottom: auto;
    left: auto;
    position: static;
    right: auto;
  }
}

:host {
  display: block;
}

